
/* ================= Client Portal: no Messages or Files tabs ================= */
for(let i=PNAVP.length-1;i>=0;i--)if(['files','messages'].includes(PNAVP[i][0]))PNAVP.splice(i,1);
PNAVP.splice(2,0,['approvals','Approvals','check',1]);
const _ovPortal=VIEWS.portal;VIEWS.portal=p=>{if(p[0]==='approvals')return _ovPortal(['requests']).replace('<h1 class="h1">Requests</h1>','<h1 class="h1">Approvals</h1>');if(p[0]==='files'||p[0]==='messages')return _ovPortal(['home']);return _ovPortal(p)};
/* ================= Whiteboard: folders + full-page canvas ================= */
const WBF=[{id:'f1',n:'Harry Kaye PT',boards:['Quiz funnel flow','Kick-off workshop']},{id:'f2',n:'Funnel Challenge',boards:['Day plan','Book outline','Promo ideas']},{id:'f3',n:'Team retros',boards:['October retro']}];
VIEWS.whiteboard=p=>{const pg=p[0]||'home';
if(pg==='board')return wbFull();
const f=pg==='folder'?WBF.find(x=>x.id===p[1]):null;
const nav=[['whiteboard/home','All boards','whiteboard'],['whiteboard/starred','Starred','star'],['whiteboard/tpl','Templates','copy']];
const card=(n,i)=>`<a class="card6 wbc" href="#/whiteboard/board/b1" data-ctx="wbb"><span class="wb-th">${['#FFE58F','#FFC2D8','#BDE8DF','#C9D8FF'].map((c,j)=>`<i style="left:${10+j*21}%;top:${18+((j+i)%2)*30}%;--c:${c}"></i>`).join('')}</span><b>${n}</b><small class="muted">${avs(['TR','AR'])} Edited ${['10 min ago','yesterday','last week'][i%3]}</small></a>`;
return shell('whiteboard',{nav,cur:f?'whiteboard/home':'whiteboard/'+pg,crumbs:f?[['Whiteboard','whiteboard/home'],[f.n]]:[['Whiteboard']],sideMid:`<div class="side-sec sx">Folders</div><div class="side-list">${WBF.map(x=>`<a href="#/whiteboard/folder/${x.id}" ${f&&f.id===x.id?'aria-current="page"':''}>${ic('folder',15)}<span>${x.n}</span><span class="count">${x.boards.length}</span></a>`).join('')}</div><button class="addrow" data-act="wbfolder">${ic('plus',15)}New folder</button>`,body:`<div class="ph6"><div><h1 class="t1">${f?f.n:'All boards'}</h1><p class="hint">${f?'Boards in this folder.':'Every board you can open. Project and client boards also open from their own app.'}</p></div><div class="acts"><button class="btn ghost sm" data-act="wbfolder">${ic('fplus',15)}New folder</button><a class="btn primary sm" href="#/whiteboard/board/new">${ic('plus',15,'',2.2)}New board</a></div></div>
${f?'':`<p class="over" style="margin-bottom:8px">Folders</p><div class="fold6" style="margin-bottom:20px">${WBF.map(x=>`<a class="fold" href="#/whiteboard/folder/${x.id}" data-ctx="wbb">${ic('folder',26)}<b>${x.n}</b><small>${x.boards.length} boards</small></a>`).join('')}</div><p class="over" style="margin-bottom:8px">Start from a template</p><div class="tplstrip">${['Blank','Funnel flow','Brainstorm','Mind map','Retro','Kanban'].map(n=>`<a class="tplb" href="#/whiteboard/board/new"><span></span>${n}</a>`).join('')}</div><p class="over" style="margin:18px 0 8px">Recent boards</p>`}<div class="cardgrid">${(f?f.boards:['Quiz funnel flow','Q4 content ideas','October retro']).map(card).join('')}</div>`})};
function wbFull(){const T=[['lock','Lock'],['hand','Hand (H)'],['cursor','Select (V)'],['shape','Rectangle (R)'],['target','Ellipse (O)'],['arrow','Arrow (A)'],['gantt','Line (L)'],['pen','Draw (P)'],['text','Text (T)'],['imgI','Image'],['sticky','Sticky note (S)'],['x','Eraser (E)']];
return `<div class="wbfull"><div class="wb" id="wb"><div class="wb-world" id="wbw">${wbItems()}</div></div>
<div class="wbx tl"><a class="wbx-b" href="#/whiteboard/home" aria-label="Back to boards">${ic('right',16).replace('<svg','<svg style="transform:scaleX(-1)"')}</a><div class="r-wrap"><button class="wbx-b" data-act="railmenu" aria-label="Apps">${ic('grid',16)}</button>${appMenu('whiteboard')}</div><span class="wbx-t"><b>Quiz funnel flow</b><small>${ic('folder',11)} Harry Kaye PT · Saved</small></span></div>
<div class="wbx tc" role="toolbar" aria-label="Tools">${T.map(([i,l],k)=>`<button class="${WB.tool===({hand:'hand',cursor:'cursor',sticky:'sticky'}[i]||'x')?'on':''}" title="${l}" aria-label="${l}" data-act="wtool:${i}"><span>${ic(i,17)}</span><small>${k+1<10?k+1:''}</small></button>`).join('')}</div>
<div class="wbx tr">${avs(['TR','AR','SN'])}<button class="wbx-b" aria-label="Comments" data-act="toast:Comments: click anywhere to pin one.">${ic('msg',16)}</button><button class="wbx-b" aria-label="Library" data-act="toast:Library: funnel shapes, stickies, icons.">${ic('copy',16)}</button><button class="btn primary sm" data-act="toast:Share: viewer, commenter or editor; link or people.">${ic('share',14)}Share</button></div>
<div class="wbx bl"><button class="wbx-b" data-act="wz:-1" aria-label="Zoom out">${ic('zout',16)}</button><b class="mono" id="wzl">90%</b><button class="wbx-b" data-act="wz:1" aria-label="Zoom in">${ic('zin',16)}</button><span class="vs"></span><button class="wbx-b" aria-label="Undo">${ic('undo',16)}</button><button class="wbx-b" aria-label="Redo">${ic('redo',16)}</button></div>
<div class="wbx br"><button class="wbx-b" aria-label="Present" data-act="toast:Presents each frame in order.">${ic('play',16)}</button><button class="wbx-b" aria-label="Export" data-act="toast:Export PNG, SVG or PDF.">${ic('download',16)}</button><button class="wbx-b" aria-label="Help" data-act="toast:Shortcuts: 1–9 tools, Space+drag to pan, Ctrl+wheel to zoom.">?</button></div></div>`}
CTX.wbb=()=>[['arrow','Open','noop'],['edit','Rename','noop'],['move','Move to folder…','noop'],['copy','Duplicate','toast:Duplicated.:ok'],['star','Star','noop'],'-',['trash','Move to trash','toast:Moved to trash.','danger']];
ACT.wbfolder=()=>dlg({title:'New folder',body:`<div class="field" style="margin-top:12px"><label>Folder name</label><input id="wbfn" placeholder="e.g. Client workshops"></div><div class="field"><label>Who can open it</label><select><option>Everyone in ${oname()}</option><option>Only me</option><option>Choose people…</option></select></div>`,acts:[['Cancel','noop'],['Create folder','wbfolder2','primary']]});
ACT.wbfolder2=()=>{WBF.push({id:'f'+Date.now(),n:($('#wbfn')?.value||'').trim()||'New folder',boards:[]});draw();toast('Folder created.','ok')};
AFTER.whiteboard=()=>wbApply();
